// Extra words that mean a ship, where the game's name doesn't contain the key's own ("ORIG_890Jump" -> orig_890j)
const SHIP_ALIAS={orig_890j:["890jump"],orig_300i:["300","315","315p","325","325a","350","350r"],   // the 300 series share the 300i hull
  superhornet:["f7cm","super_hornet"],krig_merlin:["p52"],vanguardharbringer:["harbinger"],
  bucaneer:["buccaneer"],anvl_pisces:["c8","c8x","c8r"],xian_scout:["khartu"],crus_starlifter:["hercules","m2","c2","a2"],
  crus_starfighter:["ares"],crus_star_runner:["mercury"],misc_hull_a:["hulla"],misc_hull_c:["hullc"],rsi_ursa_rover:["ursa"],
  tmbl_storm:["storm"],cnou_hoverquad:["hoverquad"],argo_mpuv:["mpuv"],aegs_idris:["idris"],anvl_valkyrie:["valkyrie"]};
const SHIP_MAKERS=new Set(["aegs","anvl","argo","banu","cnou","crus","drak","espr","krig","misc","orig","rsi","tmbl","vncl","xian","grin","mrai","xnaa","gama"]);
// The icon key for the game's ship name, or null. Whole words only ("hull_a" isn't "hull_c"); the maker counts
// for a little (aegs_idris over idris); the longest match wins (vanguardharbringer over aegs_vanguard).
const _shipIconHit=new Map();
function shipIconKey(name){ if(!name) return null; const n=String(name).toLowerCase().replace(/[^a-z0-9]+/g,"_");
  if(_shipIconHit.has(n)) return _shipIconHit.get(n);
  const w=`_${n}_`, maker=n.split("_")[0]; let best=null, score=0;
  for(const k of Object.keys(SHIP_ICONS)){ const parts=k.split("_"), mk=SHIP_MAKERS.has(parts[0])?parts[0]:null, model=(mk?parts.slice(1):parts).join("_");
    const words=[model,model.replace(/_/g,""),...(SHIP_ALIAS[k]||[])];
    for(const m of words){ if(!m||!w.includes(`_${m}_`)) continue;
      const sc=m.length*2+(mk&&mk===maker?3:0)+(SHIP_ALIAS[k]?.includes(m)?10:0);     // an alias names a variant: it wins
      if(sc>score){ score=sc; best=k; } } }
  _shipIconHit.set(n,best); return best; }
